function contactEditor(r={}){modal(r.id?'Edit Kontak':'Tambah Kontak',`<div class="form-grid">${field('name','Nama','text',r.name||'')}${field('phone','WhatsApp / Telepon','tel',r.phone||'')}${field('category','Kategori','text',r.category||'',[],false)}${field('notes','Keterangan','textarea',r.notes||'',[],false)}</div><p class="muted">Nomor diperiksa terhadap customer dan kontak tambahan.</p>`,async d=>api('/api/contacts'+(r.id?'/'+r.id:''),{method:r.id?'PUT':'POST',body:d}));}
function contactUpload(){
 let payload,result,generation=0;modal('Upload Database Kontak',`<p>Unduh Google Sheets sebagai Excel (.xlsx) atau CSV, lalu pilih file di sini. Dibaca dari lembar pertama, dengan judul kolom pada baris pertama. Maksimal 2.000 baris / 5 MB.</p><a href="/api/contacts/template" class="link">Unduh template CSV</a><label>File kontak<input id="contactFile" type="file" accept=".xlsx,.csv"></label><div id="contactMapping"></div><div id="contactPreview" aria-live="polite"></div><p class="muted">Hanya baris siap yang disimpan. Duplikat dilewati tanpa menimpa data lama; baris bermasalah perlu diperbaiki dan diunggah ulang.</p><button type="button" class="primary" id="commitContacts" disabled>Upload & Simpan</button>`,null,{wide:true});
 const report=async()=>{const version=++generation;$('#commitContacts').disabled=true;const next=await api('/api/contacts/preview',{method:'POST',body:payload});if(version!==generation||!$('#contactPreview'))return;result=next;const cols=result.headers.map((h,i)=>({id:String(i),name:h||'Kolom '+(i+1)}));$('#contactMapping').innerHTML='<div class="form-grid">'+[['name','Kolom nama'],['phone','Kolom nomor'],['category','Kolom kategori'],['notes','Kolom keterangan']].map(([k,label])=>field('map_'+k,label,'select',result.mapping[k],cols,false)).join('')+'</div><button type="button" class="secondary" id="readContacts">Baca Ulang Kolom</button>';$('#readContacts').onclick=safe(async()=>{payload.mapping=Object.fromEntries(['name','phone','category','notes'].map(k=>[k,$('[name=map_'+k+']').value===''?-1:Number($('[name=map_'+k+']').value)]));await report();});$$('#contactMapping select').forEach(el=>el.onchange=()=>{$('#commitContacts').disabled=true;});const ready=result.rows.filter(r=>r.status==='Siap').length,dup=result.rows.filter(r=>r.status==='Duplikat').length,bad=result.rows.length-ready-dup;$('#contactPreview').innerHTML=result.needsMapping?'<p>Pilih kolom nama dan nomor, lalu klik Baca Ulang Kolom.</p>':`<h3>${ready} siap · ${dup} duplikat · ${bad} perlu diperbaiki</h3><p>Pratinjau ${Math.min(100,result.rows.length)} dari ${result.rows.length} baris; duplikat dan kesalahan ditampilkan lebih dahulu.</p><div class="table-scroll" style="max-height:320px;overflow:auto"><table><thead><tr><th>Baris</th><th>Nama</th><th>Nomor</th><th>Status</th><th>Keterangan</th></tr></thead><tbody>${[...result.rows.filter(r=>r.status!=='Siap'),...result.rows.filter(r=>r.status==='Siap')].slice(0,100).map(r=>`<tr><td>${r.line}</td><td>${esc(r.name)}</td><td>${esc(r.phone)}</td><td>${esc(r.status)}</td><td>${esc(r.message)}</td></tr>`).join('')}</tbody></table></div>`;$('#commitContacts').disabled=!ready;$('#commitContacts').textContent=`Upload & Simpan ${ready} Kontak`;};
 $('#contactFile').onchange=async e=>{const file=e.target.files[0],version=++generation;payload=null;$('#commitContacts').disabled=true;$('#contactPreview').textContent='Membaca file…';try{if(!file)return;if(file.size>5e6)throw Error('Maksimal ukuran file 5 MB.');const format=file.name.toLowerCase().endsWith('.xlsx')?'xlsx':file.name.toLowerCase().endsWith('.csv')?'csv':'';if(!format)throw Error('Gunakan Excel .xlsx atau CSV.');const loaded={format,content:format==='csv'?await file.text():await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('File gagal dibaca.'));reader.readAsDataURL(file);})};if(version!==generation||!$('#contactPreview'))return;payload=loaded;await report();}catch(err){if($('#contactPreview'))$('#contactPreview').textContent=err.message;}};
 $('#commitContacts').onclick=async e=>{e.target.disabled=true;try{const r=await api('/api/contacts/import',{method:'POST',body:payload});closeModal();await contactsPage();toast(`${r.inserted} kontak ditambahkan, ${r.duplicates} duplikat dilewati, ${r.invalid} baris perlu diperbaiki.`);}catch(err){$('#contactPreview').textContent=err.message;e.target.disabled=false;}};
}
