 if(!workTabs.has(current)){const frame=document.createElement('iframe');frame.title=titles[current];frame.src='/?workspace=1#'+encodeURIComponent(current);frame.className='work-frame';$('#workPanes').append(frame);workTabs.set(current,{frame,stale:false});}
