const can=(key,action='view')=>key==='attendance'?!!session?.user:key==='attendanceadmin'?session?.user?.role==='SUPER ADMIN':(session?.user?.role!=='SUPER ADMIN'&&['master','posmaster'].includes(group[key]||key)&&['create','edit','delete'].includes(action)&&!session?.user?.permissions?.masterchanges?.includes(action))?false:key==='activity'?session?.user?.role==='SUPER ADMIN':session?.user?.role==='SUPER ADMIN'||session?.user?.permissions[group[key]||key]?.includes(action);
async function api(url,options={}){const res=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});const d=await res.json();if(!res.ok){if(res.status===401&&session?.user){session.user=null;if(embeddedWorkspace)parent.postMessage({type:'workspace-expired'},location.origin);auth();}throw Error(d.error||'Permintaan gagal.');}if(embeddedWorkspace&&options.method&&options.method!=='GET')parent.postMessage({type:'workspace-changed'},location.origin);return d;}
function toast(message){let el=$('#toast');if(!el){el=document.createElement('div');el.id='toast';document.body.append(el);}el.textContent=message;el.className='toast show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5000);}
const safe=fn=>async(...args)=>{try{await fn(...args);}catch(e){toast(e.message);}};
