function bulkRecords(kind){
 const invoiceFields=[['customerId','Customer','customers'],['unitId','Unit Bisnis','units'],['date','Tanggal Invoice','date'],['dueDate','Jatuh Tempo','date'],['bankId','Rekening Pembayaran','banks',false],['eventDate','Tanggal Acara','date',false],['eventStart','Jam Mulai','time',false],['eventEnd','Jam Selesai','time',false],['discount','Diskon Invoice','number'],['other','Biaya Lainnya','number'],['notes','Catatan','textarea',false]];
 const userFields=[['name','Nama'],['username','Username'],['password','Password','password'],['role','Role',Object.keys(session.roles)],['active','Aktif','checkbox']];
 const fields=kind==='invoices'?invoiceFields:kind==='users'?userFields:spec[kind];if(!fields)return;
 let serial=0;
 modal('Input Massal — '+(titles[kind]||'Dana Petty Cash'),'<p class="muted">Maksimal 100 baris. Semua baris disimpan bersama. Jika ada kesalahan, perbaiki baris yang disebutkan lalu simpan kembali.</p>'+(kind==='users'?'<p class="muted">Izin pengguna mengikuti role yang dipilih. Izin khusus dapat diatur melalui Edit Pengguna.</p>':'')+'<div id="batchRows"></div><button type="button" class="secondary" id="addBatchRow">＋ Tambah Baris</button><p id="batchTotal" aria-live="polite"></p>',async(d,form)=>{
  const result=[];
  const read=async(container,selector)=>{const data={};for(const el of container.querySelectorAll(selector))data[el.dataset.key]=el.type==='file'?await fileValue(el.files[0]):el.type==='checkbox'?el.checked:el.type==='number'&&el.value!==''?Number(el.value):el.value;return data;};
  for(const row of form.querySelectorAll('.batch-row')){
   const data=await read(row,':scope > .form-grid [data-key]');
   if(kind==='invoices'){data.items=[];for(const item of row.querySelectorAll('.batch-item'))data.items.push(await read(item,'[data-key]'));if(!data.items.length)throw Error('Setiap invoice harus memiliki minimal satu item.');}
   result.push(data);
  }
  if(!result.length)throw Error('Tambahkan minimal satu baris.');
  await api('/api/batch/'+kind,{method:'POST',body:{rows:result}});
 },{wide:true,save:'Simpan Semua'});
 const renderField=([key,label,type='text',required=true],values,prefix)=>{
  let list=[];if(Array.isArray(type)){list=type;type='select';}else if(lookups[type]){list=lookups[type];if(type==='stocks'){list=list.filter(x=>!['warehouse','teko'].includes(current)||x.location===(current==='teko'?'Teko Marala':'Gudang')).map(x=>({...x,name:x.name+' — '+x.location}));}type='select';}
  return field(prefix+key,label,type,values[key]??'',list,required).replace('name="'+prefix+key+'"','data-key="'+key+'" name="'+prefix+key+'"');
 };
 const total=()=>{const rows=$$('#batchRows > .batch-row');$('#batchTotal').textContent=rows.length+' baris'+(fields.some(f=>f[0]==='amount')?' · Total '+money(rows.reduce((sum,r)=>sum+Number(r.querySelector('[data-key="amount"]').value||0),0)):'');$('#addBatchRow').disabled=rows.length>=100;};
 const add=()=>{
  const id=++serial,defaults={date:today(),dueDate:today(),cost:0,price:0,minTeko:0,minWarehouse:0,maxTeko:100,maxWarehouse:100,from:'Gudang',to:'Teko Marala',active:true,direction:'Masuk',status:'Draft',role:'STAFF',discount:0,other:0};
  const prev=$('#batchRows > .batch-row:last-child');for(const key of ['date','dueDate','unitId','category','method','source','location','stockCategory']){const el=prev?.querySelector('[data-key="'+key+'"]');if(el)defaults[key]=el.value;}
  const row=document.createElement('fieldset');row.className='bulk-expense-row batch-row';row.innerHTML='<legend>Baris '+id+'</legend><div class="form-grid">'+fields.filter(f=>!(['expenses','procurements'].includes(kind)&&f[0]==='number')).map(f=>renderField(f,defaults,'batch_'+id+'_')).join('')+'</div>'+(kind==='invoices'?'<h3>Item Invoice</h3><div class="batch-items"></div><button type="button" class="secondary add-batch-item">＋ Tambah Item</button>':'')+'<p class="muted batch-hint"></p><button type="button" class="secondary remove-batch-row">Hapus Baris</button>';
  $('#batchRows').append(row);const get=key=>row.querySelector(':scope > .form-grid [data-key="'+key+'"]');
  if(['opnames','movements'].includes(kind)){bindStockSelection(get);if(defaults.stockCategory){get('stockCategory').value=defaults.stockCategory;get('stockCategory').onchange();}}if(kind==='procurements')bindProcurementFields(get);if(['sales','expenses'].includes(kind))bindFinanceFields(kind,get);
  for(const key of ['quantity','actual','minTeko','minWarehouse','maxTeko','maxWarehouse'])if(get(key))get(key).step='0.001';
  const filterProducts=()=>{if(get('productId'))get('productId').innerHTML=options(lookups.products.filter(p=>p.unitId===get('unitId').value),get('productId').value);};
  if(get('unitId')&&get('productId')){get('unitId').onchange=filterProducts;filterProducts();}
  if(kind==='payments')get('invoiceId').onchange=()=>{const i=lookups.invoices.find(i=>i.id===get('invoiceId').value);row.querySelector('.batch-hint').textContent=i?'Sisa tagihan '+money(i.balance)+'. Semua baris pembayaran diperiksa bersama saat disimpan.':'';};
  if(kind==='invoices'){
   let itemId=0;const itemFields=[['productId','Produk / Jasa','select'],['name','Nama pada Invoice'],['qty','Jumlah','number'],['unit','Satuan'],['price','Harga Satuan','number'],['discount','Diskon Item','number'],['notes','Catatan Item','text',false]];
   const refreshItem=item=>{const select=item.querySelector('[data-key="productId"]');select.innerHTML=options(lookups.products.filter(p=>p.unitId===get('unitId').value),select.value);};
   const addItem=()=>{const item=document.createElement('section');item.className='batch-item bulk-expense-row';item.innerHTML='<div class="form-grid">'+itemFields.map(f=>renderField(f,{qty:1,discount:0},'item_'+id+'_'+(++itemId)+'_')).join('')+'</div><button type="button" class="secondary">Hapus Item</button>';row.querySelector('.batch-items').append(item);refreshItem(item);item.querySelector('[data-key="qty"]').step='0.001';item.querySelector('[data-key="productId"]').onchange=e=>{const p=lookups.products.find(p=>p.id===e.target.value);if(p)for(const k of ['name','unit','price'])item.querySelector('[data-key="'+k+'"]').value=p[k];};item.querySelector('button').onclick=()=>item.remove();};
   const updateUnit=()=>{row.querySelectorAll('.batch-item').forEach(refreshItem);const event=['Sewa Ruangan','Vendor'].includes(lookups.units.find(u=>u.id===get('unitId').value)?.name);for(const k of ['eventDate','eventStart','eventEnd'])get(k).required=event;};
   get('unitId').onchange=updateUnit;row.querySelector('.add-batch-item').onclick=addItem;addItem();updateUnit();
  }
  row.querySelector('.remove-batch-row').onclick=()=>{row.remove();total();};row.oninput=total;total();
 };
 $('#addBatchRow').onclick=add;add();add();
}
async function importExpenses(){modal('Import Pengeluaran',`<p>Gunakan template, kosongkan nomor agar dibuat otomatis, isi tanggal YYYY-MM-DD, dan nominal tanpa pemisah ribuan. Maksimal 2.000 baris.</p><a class="download-link" href="/api/import/template">Unduh template Excel</a>${field('file','File Excel (.xlsx) atau CSV','file')}<button type="button" class="secondary" id="previewImport">Periksa & Pratinjau</button><div id="importPreview"></div>`,null,{wide:true});$('#editor input[type=file]').accept='.xlsx,.csv';$('#previewImport').onclick=safe(async()=>{const file=$('#editor input[type=file]').files[0];if(!file)throw Error('Pilih file terlebih dahulu.');if(file.size>5e6)throw Error('Ukuran file maksimal 5 MB.');const isExcel=file.name.toLowerCase().endsWith('.xlsx');const content=isExcel?(await fileValueForImport(file)).split(',')[1]:await file.text();const result=await api('/api/import/preview',{method:'POST',body:{format:isExcel?'xlsx':'csv',content}});const invalid=result.filter(r=>r.error).length;$('#importPreview').innerHTML=`<p>${result.length} baris · ${invalid} error. ${invalid?'Perbaiki file lalu periksa kembali.':'Siap disimpan.'}</p><div class="table-scroll"><table><thead><tr><th>Baris</th><th>Nomor</th><th>Nominal</th><th>Hasil validasi</th></tr></thead><tbody>${result.map(r=>`<tr><td>${r.row}</td><td>${esc(r.data.number)}</td><td>${money(r.data.amount)}</td><td class="${r.error?'danger':''}">${esc(r.error||'Valid')}</td></tr>`).join('')}</tbody></table></div><button class="primary" type="button" id="commitImport" ${invalid||!result.length?'disabled':''}>Simpan ${result.length} Pengeluaran</button>`;$('#commitImport').onclick=safe(async e=>{e.target.disabled=true;try{const saved=await api('/api/import/commit',{method:'POST',body:{rows:result.map(r=>r.data)}});closeModal();await loadPage();toast(saved.count+' pengeluaran berhasil diimpor.');}catch(err){e.target.disabled=false;throw err;}});});}
function fileValueForImport(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
async function settingsPage(){if(current==='appearance'){$('#content').innerHTML=header()+`<section class="card panel"><h3>Tema Aplikasi</h3><p>Pilihan disimpan pada perangkat ini.</p><div class="button-row"><button class="secondary" id="lightTheme">Mode Terang</button><button class="secondary" id="darkTheme">Mode Gelap</button></div></section>`;$('#lightTheme').onclick=()=>theme('light');$('#darkTheme').onclick=()=>theme('dark');return;}
 if(current==='application'){const appSettings=(await api('/api/settings')).application||{};$('#content').innerHTML=header()+applicationForm(appSettings)+`<section class="card panel"><h3>Pasang Aplikasi</h3><p>Gunakan menu browser “Install aplikasi” atau “Tambahkan ke layar utama”. Transaksi membutuhkan koneksi ke server.</p><button id="installApp" class="primary">Pasang Aplikasi</button></section>${session.user.role==='SUPER ADMIN'?`<section class="card panel"><h3>Data & Migrasi</h3><p>Impor data prototipe dari browser ini. Data asli tetap disimpan; impor identik tidak akan digandakan.</p><div class="button-row">${!session.setupTokenRequired?'<button class="primary" id="migrateData">Impor Data Lama</button>':''}<a class="secondary" href="/api/backup" download="Cadangan_BUMM_Marala.json">Unduh Cadangan Data</a><a class="secondary" href="/api/backup?full=1" download="Cadangan_Pemulihan_BUMM_Marala.json">Unduh Cadangan Pemulihan</a></div><label style="margin-top:16px">Impor cadangan prototipe dari perangkat/alamat lama<input id="legacyFile" type="file" accept=".json"></label><p class="muted">Cadangan Pemulihan berisi seluruh data dan akun. Simpan secara privat, jangan unggah ke GitHub. Cadangan ini dapat dipulihkan saat pengaturan awal aplikasi online yang masih kosong.</p></section>`:''}`;bindApplicationForm(appSettings);$('#installApp').onclick=safe(async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('Buka menu browser untuk memasang aplikasi. HTTPS atau localhost diperlukan.');});if($('#legacyFile'))$('#legacyFile').onchange=safe(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>6e6)throw Error('Cadangan terlalu besar.');const data=JSON.parse(await file.text());if(data.records||data.format==='marala-cloud-snapshot')throw Error('Ini cadangan server, bukan prototipe. Gunakan pemulihan database server.');if(!confirm('Impor cadangan data prototipe ini?'))return;const result=await api('/api/migrate',{method:'POST',body:data});toast(result.message);});if($('#migrateData'))$('#migrateData').onclick=safe(async()=>{const raw=localStorage.getItem('bumm-marala-prototype');const legacy=await api('/api/legacy-seed');const saved=raw?JSON.parse(raw):{};if(!confirm('Impor data prototipe dan data browser yang tersedia? Data lama tetap dipertahankan.'))return;const r=await api('/api/migrate',{method:'POST',body:{...legacy,...saved}});toast(r.message+' '+r.count+' data ditambahkan.');});return;}
 const s=await api('/api/settings'),isIdentity=current==='identity',data=isIdentity?s.identity:s.invoice;const names={showLogo:'Tampilkan logo',showAddress:'Tampilkan alamat',showPhone:'Tampilkan telepon',showBank:'Tampilkan rekening',showNotes:'Tampilkan catatan',showDiscount:'Tampilkan diskon nol',showOther:'Tampilkan biaya tambahan nol',showSignature:'Tampilkan tanda tangan',showFooter:'Tampilkan footer',showStatus:'Tampilkan status pembayaran',showPayments:'Tampilkan riwayat pembayaran pada cetakan'};$('#content').innerHTML=header()+`<form id="settingsForm" class="card panel settings-form">${isIdentity?`<div class="form-grid">${field('name','Nama BUMM','text',data.name)}${field('organization','Nama Organisasi','text',data.organization,[],false)}${field('address','Alamat','textarea',data.address,[],false)}${field('phone','Telepon','tel',data.phone,[],false)}${field('email','Email','email',data.email,[],false)}${field('website','Website','url',data.website,[],false)}${field('logo','Logo','file','',[],false)}</div>${data.logo?`<img src="${esc(data.logo)}" alt="Logo saat ini" class="settings-logo">`:''}`:`<div class="form-grid">${field('prefix','Prefix Nomor Invoice','text',data.prefix)}${field('color','Warna Invoice','color',data.color)}${field('footer','Teks Footer','textarea',data.footer,[],false)}</div><div class="check-grid">${Object.entries(names).map(([k,l])=>field(k,l,'checkbox',data[k])).join('')}</div><p class="muted">Perubahan digunakan pada invoice baru. Identitas, rekening, dan pengaturan invoice lama tetap sesuai saat dibuat. Diskon dan biaya bernilai bukan nol selalu ditampilkan agar hitungan jelas.</p>`}<p class="form-error" role="alert"></p>${can(current,'edit')?'<button class="primary">Simpan Perubahan</button>':''}</form>`;$('#settingsForm').onsubmit=async e=>{e.preventDefault();try{const d=formData(e.target);if(isIdentity)d.logo=await fileValue(e.target.elements.logo.files[0])||data.logo;await api('/api/settings',{method:'POST',body:{[isIdentity?'identity':'invoice']:d}});await shell();toast('Pengaturan disimpan.');}catch(e){$('.form-error').textContent=e.message;}};}
