function userEditor(u={}){const role=u.role||'STAFF';modal(u.id?'Edit Pengguna':'Tambah Pengguna',`<div class="form-grid">${field('name','Nama','text',u.name)}${field('username','Username','text',u.username)}${field('password',u.id?'Password Baru (kosongkan jika tetap)':'Password','password','',[],!u.id)}${field('role','Role','select',role,Object.keys(session.roles))}${field('active','Aktif','checkbox',u.active!==0)}</div><h3>Izin Akses</h3><div class="table-scroll" id="permissions"></div>`,async d=>{d.permissions=Object.fromEntries(session.modules.map(m=>[m,$$(`#permissions input[data-module="${m}"]:checked`).map(e=>e.value)]));await api('/api/users'+(u.id?'/'+u.id:''),{method:u.id?'PUT':'POST',body:d});},{wide:true});const draw=p=>$('#permissions').innerHTML=`<table><thead><tr><th>Modul</th>${session.actions.map(a=>`<th>${({view:'Lihat',create:'Tambah',edit:'Edit',delete:'Hapus',approve:'Setujui',export:'Ekspor'})[a]}</th>`).join('')}</tr></thead><tbody>${session.modules.map(m=>`<tr><td>${({masterchanges:'Izin manual ubah master (Tambah/Edit/Hapus)',pos:'Kasir Teko',posmaster:'Master Produk Teko',posreports:'Laporan Teko',posapproval:'Rekap dan Approval Teko',master:'Master Data',stock:'Stok',reports:'Laporan',settings:'Pengaturan',users:'Pengguna'})[m]||titles[m]}</td>${session.actions.map(a=>`<td><input aria-label="${m} ${a}" type="checkbox" data-module="${m}" value="${a}" ${(p[m]||[]).includes(a)?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table>`;draw(u.permissions||session.roles[role]);$('#editor [name=role]').onchange=e=>draw(session.roles[e.target.value]);}
(async()=>{try{await refreshApplicationBrand();session=await api('/api/session');if(session.user)await shell();else auth();if('serviceWorker'in navigator)await navigator.serviceWorker.register('/sw.js');}catch(e){$('#app').innerHTML=`<main class="auth"><section class="card"><h1>Aplikasi belum terhubung</h1><p>${esc(e.message)}</p><p>Jalankan server BUMM Marala lalu buka alamat aplikasi dari server.</p></section></main>`;}})();
function actorLabel(who){return who?(who.name+(who.username?' (@'+who.username+')':'')):'Tidak tercatat (data lama)';}
function traceTime(value){return value?new Date(value).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})+' WIB':'—';}
function traceSummary(t={}){return '<span class="trace-summary">'+esc(t?.createdBy?.name||t?.createdBy?.username||'Tidak tercatat')+'</span>';}
const activityLabels={create:'Tambah',edit:'Ubah',delete:'Arsipkan / tarik rekap',transfer:'Transfer stok',import:'Impor data lama',migration:'Impor data lama',settings:'Ubah pengaturan','user-save':'Simpan akun / izin','pos-product':'Simpan produk kasir','pos-product-create':'Tambah produk kasir','pos-product-edit':'Ubah produk kasir','pos-sale':'Penjualan kasir','pos-void':'Batalkan transaksi','pos-submit':'Ajukan rekap','pos-approve':'Setujui rekap','pos-reopen':'Buka revisi'};
function activityTable(events){return posTable(['Waktu (WIB)','Akun','Tindakan','Data'],events.map(e=>[esc(traceTime(e.at)),esc(actorLabel(e.actor)),esc(activityLabels[e.action]||e.action),esc(e.target||e.entity)]));}
async function recordHistory(id){const d=await api('/api/activity?recordId='+encodeURIComponent(id));modal('Jejak Input',traceSummary(d.record._trace)+'<p class="muted">Akun mengikuti pengguna yang login. Identitas sumber data impor lama belum tentu tercatat. Waktu dalam WIB.</p>'+activityTable(d.events),null,{wide:true});}
async function activityPage(){const from=filters.from||today(),to=filters.to||today(),q=filters.q||'',offset=filters.activityOffset||0,d=await api('/api/activity?'+new URLSearchParams({from,to,q,offset}));$('#content').innerHTML=header()+'<form id="activityFilter" class="pos-date-filter">'+field('from','Dari tanggal','date',from)+field('to','Sampai tanggal','date',to)+field('q','Cari akun / data','search',q,[],false)+'<button class="primary">Cari Aktivitas</button></form><p class="muted">Riwayat akun yang melakukan tindakan. Nama akun disimpan saat tindakan berlangsung untuk aktivitas baru. Tidak mencatat password atau isi lampiran.</p><section class="card panel"><p>'+d.total+' aktivitas</p>'+activityTable(d.events)+'<div class="button-row"><button id="activityPrev" class="secondary" '+(!offset?'disabled':'')+'>Sebelumnya</button><button id="activityNext" class="secondary" '+(offset+d.limit>=d.total?'disabled':'')+'>Berikutnya</button></div></section>';$('#activityFilter').onsubmit=safe(async e=>{e.preventDefault();filters={...formData(e.target),activityOffset:0};await activityPage();});$('#activityPrev').onclick=safe(async()=>{filters.activityOffset=Math.max(0,offset-d.limit);await activityPage();});$('#activityNext').onclick=safe(async()=>{filters.activityOffset=offset+d.limit;await activityPage();});}
function applicationForm(a){return `<form id="applicationForm" class="card panel settings-form"><h3>Nama & Ikon Aplikasi</h3><div class="form-grid">${field('name','Nama aplikasi','text',a.name||'BUMM Marala Management System')}${field('shortName','Nama singkat di layar utama','text',a.shortName||'BUMM Marala')}<label>Gambar aplikasi<input name="appIcon" type="file" accept="image/png,image/jpeg,image/webp"></label></div><img id="appIconPreview" class="settings-logo" src="${esc(a.icon512||'/icon.svg')}" alt="Pratinjau ikon aplikasi"><p class="muted">Gunakan gambar persegi PNG, JPG, atau WebP, maksimal 2 MB. Nama dan ikon ini terlihat saat aplikasi dipasang. Pembaruan aplikasi yang sudah terpasang mengikuti browser/perangkat; mungkin perlu konfirmasi atau pemasangan ulang.</p><p class="form-error" role="alert"></p>${can('application','edit')?'<button class="primary">Simpan Nama & Ikon</button>':''}</form>`;}
async function applicationIcons(file){if(file.size>2*1024*1024)throw Error('Gambar maksimal 2 MB.');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Gunakan PNG, JPG, atau WebP.');const src=await fileValue(file),img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Gambar tidak dapat dibaca.'));img.src=src;});const icons={};for(const size of [192,512]){const c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d');ctx.clearRect(0,0,size,size);const scale=size/Math.max(img.width,img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(size-w)/2,(size-h)/2,w,h);icons['icon'+size]=c.toDataURL('image/png');}return icons;}
function bindApplicationForm(a){const form=$('#applicationForm');let selected={},pending=Promise.resolve(true);form.elements.appIcon.onchange=()=>{selected={};pending=(async()=>{try{const file=form.elements.appIcon.files[0];if(file){selected=await applicationIcons(file);$('#appIconPreview').src=selected.icon512;}else $('#appIconPreview').src=a.icon512||'/icon.svg';form.querySelector('.form-error').textContent='';return true;}catch(e){form.querySelector('.form-error').textContent=e.message;return false;}})();};form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;if(!can('application','edit'))return;button.disabled=true;try{if(!await pending&&form.elements.appIcon.files.length)return;await api('/api/settings',{method:'POST',body:{application:{name:form.elements.name.value,shortName:form.elements.shortName.value,...selected}}});await refreshApplicationBrand();toast('Nama dan ikon aplikasi disimpan.');}catch(err){form.querySelector('.form-error').textContent=err.message;}finally{button.disabled=false;}};}
async function refreshApplicationBrand(){const a=await api('/api/application-brand');document.title=a.name;document.querySelector('link[rel="icon"]').href=a.icon;let touch=document.querySelector('link[rel="apple-touch-icon"]');if(!touch){touch=document.createElement('link');touch.rel='apple-touch-icon';document.head.append(touch);}touch.href=a.icon;}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshApplicationBrand().catch(()=>{});});


function setMenuOpen(open,restoreFocus=true){const sidebar=$('#sidebar');if(!sidebar)return;const mobile=window.matchMedia('(max-width:1050px)').matches;open=Boolean(open&&mobile);sidebar.classList.toggle('mobile-open',open);sidebar.inert=mobile&&!open;$('#menuBackdrop').hidden=!open;$('.main').inert=open;document.body.classList.toggle('menu-is-open',open);$('#menuButton').setAttribute('aria-expanded',String(open));if(open)$('#closeMenu').focus();else if(restoreFocus&&mobile)$('#menuButton').focus();}
window.matchMedia('(max-width:1050px)').addEventListener('change',()=>setMenuOpen(false,false));
document.addEventListener('keydown',e=>{if(!$('#sidebar')?.classList.contains('mobile-open'))return;if(e.key==='Escape'){e.preventDefault();setMenuOpen(false);}if(e.key==='Tab'){const items=Array.from($('#sidebar').querySelectorAll('button,a,summary')).filter(el=>el.getClientRects().length&&!el.disabled),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});


function bindFinanceFields(kind,get){
 const keys=kind==='sales'?['quantity','salePrice','unitCost']:['quantity','unitPrice'];
 const calc=()=>{const enabled=keys.every(k=>get(k).value!=='');get('amount').readOnly=enabled;if(kind==='sales')get('cost').readOnly=enabled;if(enabled){get('amount').value=Math.round(Number(get('quantity').value)*Number(get(keys[1]).value));if(kind==='sales')get('cost').value=Math.round(Number(get('quantity').value)*Number(get('unitCost').value));}};
 keys.forEach(k=>get(k).addEventListener('input',calc));calc();
 if(kind==='expenses'){
  const suggestions=['Gaji dan Upah','Es dan Gas','Kebersihan','Listrik dan Air','Transportasi','Perlengkapan','Perbaikan','Komisi','Vendor','Operasional Lainnya'];
  if(!$('#expenseCategories')){const list=document.createElement('datalist');list.id='expenseCategories';list.innerHTML=suggestions.map(x=>`<option value="${esc(x)}">`).join('');document.body.append(list);}get('category').setAttribute('list','expenseCategories');
  get('costClass').closest('label').insertAdjacentHTML('afterend','<p class="muted">HPP = biaya langsung tambahan. Pilih “Tercakup HPP invoice” hanya bila nominal ini sudah termasuk HPP invoice terkait. Jumlah dan harga satuan boleh dikosongkan untuk input total.</p>');
 }
}
function financeTable(headers,data){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${data.map(row=>'<tr>'+row.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('')||`<tr><td colspan="${headers.length}">Belum ada data pada periode ini.</td></tr>`}</tbody></table></div>`;}
async function profitPage(){
 if(!filters.from&&!filters.to&&!filters.preset){filters.from=today().slice(0,7)+'-01';filters.to=today();filters.preset='Bulan ini';}
 const d=await api('/api/report?'+query()),rate=v=>v===null?'Tidak tersedia':new Intl.NumberFormat('id-ID',{style:'percent',maximumFractionDigits:1}).format(v);
 const admin=session.user.role==='SUPER ADMIN'&&!d.approval;
 const tableRows=[['PENDAPATAN','',''],...d.units.filter(u=>!filters.unitId||u.id===filters.unitId).map(u=>[esc(u.name),money(u.revenue),u.group!==u.name?esc(u.group):'']),['<strong>TOTAL OMZET</strong>',`<strong>${money(d.revenue)}</strong>`,''],['HARGA POKOK PENJUALAN','',''],...d.units.filter(u=>!filters.unitId||u.id===filters.unitId).map(u=>['HPP '+esc(u.name),money(u.cost),'']),['<strong>TOTAL HPP</strong>',`<strong>${money(d.cost)}</strong>`,''],['<strong>LABA KOTOR</strong>',`<strong>${money(d.grossProfit)}</strong>`,rate(d.grossMargin)],['BIAYA OPERASIONAL','',''],...d.categories.map(c=>[esc(c.name),money(c.amount),'']),['<strong>TOTAL BIAYA OPERASIONAL</strong>',`<strong>${money(d.outgoing)}</strong>`,''],['<strong>LABA BERSIH</strong>',`<strong>${money(d.profit)}</strong>`,rate(d.netMargin)]];
 $('#content').innerHTML=header(exportButtons('profit')+(admin?'<button class="secondary" id="financeSettings">Pengaturan Laporan</button>':''))+filterBar()+reportApprovalBanner(d)+`<p class="notice">Omzet mengikuti tanggal uang masuk. HPP invoice dialokasikan proporsional. Biaya mengikuti tanggal pembayaran, ditambah penyusutan pada akhir bulan. Rekap kasir yang belum disetujui belum masuk omzet.</p>`+metricCards([['Omzet',money(d.revenue)],['Laba kotor',money(d.grossProfit)],['Biaya operasional',money(d.outgoing)],['Laba bersih',money(d.profit)]])+`<section class="card panel"><h2>Laporan Laba Rugi Manajemen</h2><p>${esc(filters.from||'Awal pencatatan')} s.d. ${esc(filters.to||'Seluruh data')}</p>${financeTable(['Uraian','Nominal','Margin / kelompok'],tableRows)}</section><section class="card panel"><h3>Periksa sebelum diserahkan (${d.warnings.length})</h3><p>Excel menyertakan catatan ini agar angka yang belum lengkap tidak dianggap final.</p>${financeTable(['Tanggal','Referensi','Perlu diperiksa'],d.warnings.map(w=>[esc(w.date),esc(w.number),esc(w.message)]))}</section><details class="card panel"><summary>Rincian pendapatan (${d.entries.length})</summary>${financeTable(['Tanggal masuk','Referensi','Unit','Keterangan','Omzet','HPP'],d.entries.map(e=>[esc(e.date),esc(e.number),esc(e.unitName),esc(e.description),money(e.amount),money(e.cost)]))}</details><details class="card panel"><summary>Rincian biaya (${d.expenses.length})</summary>${financeTable(['Tanggal','Nomor','Kategori','Kelompok','Keterangan','Nominal'],d.expenses.map(e=>[esc(e.date),esc(e.number),esc(e.category),esc(e.costClass),esc(e.description),money(e.amount)]))}</details><details class="card panel"><summary>Aset dan penyusutan (${d.assets.length})</summary><p>Garis lurus, satu bulan penuh pada akhir bulan. Pengaturan tidak mengubah nilai pembelian asli.</p>${financeTable(['Aset','Perolehan','Masa manfaat','Nilai buku','Beban periode','Pengaturan'],d.assets.map(a=>[esc(a.name),money(a.amount),a.plan?a.plan.life+' bulan':'Belum diatur',money(a.bookValue),money(a.expense),admin?`<button class="link" data-plan="${esc(a.id)}">Atur penyusutan</button>`:'']))}</details>`;
 bindFilter();bindExports();
 if(admin){$('#financeSettings').onclick=safe(async()=>{const {config}=await api('/api/finance/settings');modal('Pengaturan Laporan',`<p>Kelompok pendapatan membantu menjelaskan rincian unit bisnis. Saldo awal Petty Cash cukup ditetapkan sekali dan diteruskan ke bulan berikutnya.</p><div class="form-grid">${field('pettyStart','Tanggal saldo awal (tanggal 1)','date',config.pettyStart||'',[],false)}${field('pettyOpening','Saldo awal Petty Cash','number',config.pettyOpening??'',[],false)}${lookups.units.map(u=>field('group_'+u.id,'Kelompok untuk '+u.name,'text',config.unitGroups?.[u.id]||u.name)).join('')}</div>`,async v=>{const body={unitGroups:Object.fromEntries(lookups.units.map(u=>[u.id,v['group_'+u.id]]))};if(v.pettyOpening!==''||v.pettyStart){body.pettyOpening=v.pettyOpening;body.pettyStart=v.pettyStart;}await api('/api/finance/settings',{method:'POST',body});},{wide:true});});
 $$('[data-plan]').forEach(b=>b.onclick=()=>{const a=d.assets.find(a=>a.id===b.dataset.plan);modal('Penyusutan — '+a.name,`<p>Nilai perolehan ${money(a.amount)}. Penyusutan dimulai pada akhir bulan yang dipilih.</p><div class="form-grid">${field('life','Masa manfaat (bulan)','number',a.plan?.life||'')}${field('start','Bulan mulai','month',a.plan?.start||a.date.slice(0,7))}${field('residual','Nilai sisa setelah masa manfaat','number',a.plan?.residual??0)}</div>`,async v=>{await api('/api/finance/asset/'+a.id,{method:'PUT',body:v});});});}
}
function bindProcurementFields(get){
 const show=(key,on,required=false)=>{const el=get(key);if(!el)return;el.closest('label').hidden=!on;el.disabled=!on;el.required=on&&required;};
 const recalc=()=>{get('amount').value=Math.round(Number(get('quantity').value||0)*Number(get('price').value||0));};
 const update=()=>{const inventory=get('type').value==='Persediaan';show('stockItemId',inventory,true);show('location',inventory,true);for(const k of ['name','unit','assetCategory','assetLocation'])show(k,!inventory,['name','unit'].includes(k));show('bankId',get('source').value==='Rekening',true);recalc();};
 if(get('number')){get('number').readOnly=true;get('number').placeholder='Dibuat otomatis saat disimpan';}get('amount').readOnly=true;get('quantity').step='0.001';if(!get('quantity').value)get('quantity').value=1;
 get('type').addEventListener('change',update);get('source').addEventListener('change',update);get('price').addEventListener('input',recalc);get('quantity').addEventListener('input',recalc);
 get('stockItemId').addEventListener('change',()=>{const item=lookups.stockitems.find(i=>i.id===get('stockItemId').value);if(item)get('price').value=item.price;recalc();});update();
}

function bindPasswordEyes(){
 $$('[data-password-eye]').forEach(button=>{const label=button.getAttribute('aria-label'),span=$('[data-password-text="'+button.dataset.passwordEye+'"]');let timer;
 const hide=()=>{span.textContent='••••••••';button.setAttribute('aria-pressed','false');button.setAttribute('aria-label',label);clearTimeout(timer);};
 button.onclick=safe(async()=>{if(button.getAttribute('aria-pressed')==='true'){hide();return;}button.disabled=true;try{const data=await api('/api/users/'+button.dataset.passwordEye+'/password',{method:'POST',body:{}});if(!button.isConnected)return;span.textContent=data.password;button.setAttribute('aria-pressed','true');button.setAttribute('aria-label','Sembunyikan password');timer=setTimeout(hide,30000);}finally{button.disabled=false;}});
 });
}

function bindStockSelection(get){
 const location=get('location'),category=get('stockCategory'),stock=get('stockId');if(!location||!stock)return;
 const master=new Map((lookups.stockitems||[]).map(i=>[i.id,i]));
 const cat=s=>(master.has(s.stockItemId)?master.get(s.stockItemId).category:s.category)||'';
 if(category)category.innerHTML=options([{id:'__none__',name:'Belum berkategori'},...[...new Set((lookups.stockitems||[]).map(i=>i.category).filter(Boolean))].sort().map(c=>({id:c,name:c}))],category.value);
 const update=()=>{const chosen=stock.value,list=(lookups.stocks||[]).filter(s=>s.location===location.value&&(!category?.value||cat(s)===category.value||(category.value==='__none__'&&!cat(s))));stock.innerHTML=options(list.map(s=>({...s,name:s.name+' (stok '+s.quantity+')'})),list.some(s=>s.id===chosen)?chosen:'');if(!stock.value&&get('actual'))get('actual').value='';};
 location.onchange=update;if(category)category.onchange=update;stock.onchange=()=>{const s=lookups.stocks.find(s=>s.id===stock.value);if(s){if(get('actual'))get('actual').value=s.quantity;if(get('price'))get('price').value=s.price;}};update();
}


